use anyhow::{Result, ensure};
use luna_core::*;
use luna_editor::*;
use luna_model::*;
use ts_rs::TS;
fn main() -> Result<()> {
    let mut output = String::from(
        "// Generated from Rust by: cargo run -p luna-editor --example export_types\n// Do not edit by hand.\n\n",
    );
    macro_rules! emit {($($t:ty),* $(,)?)=>{$(output.push_str("export ");output.push_str(&<$t>::decl());output.push_str("\n\n");)*};}
    emit!(
        serde_json::Value,
        Value,
        InputKind,
        EntityRef,
        MessageText,
        ProcedureInput,
        Procedure,
        Conversation,
        ConversationEntry,
        ConversationNode,
        ConversationReply,
        Quest,
        QuestStage,
        NarrativeHook,
        NarrativeDraft,
        NarrativeReferenceKind,
        TemplateNarrativeReference,
        QuestStatus,
        NarrativeProgress,
        ConversationProgress,
        ConversationCheckpoint,
        QuestProgress,
        JournalEntry,
        JournalKind,
        QuestLogEntry,
        ConversationChoice,
        ConversationView,
        Argument,
        BoundArgument,
        ScopedPlacement,
        ScopedValueTarget,
        ProcedurePath,
        ProcedureCursor,
        ObjectTarget,
        ObjectInput,
        ContainerOpening,
        ObjectStorage,
        ContentRelation,
        StandardInteraction,
        StandardAction,
        InputTextReference,
        Comparison,
        Condition,
        HelpMode,
        CommandAssistance,
        HintStage,
        HintSet,
        SequenceMode,
        ExhaustionMode,
        ArithmeticOperation,
        NumericOperand,
        Effect,
        PatternPart,
        Action,
        Event,
        ValueTarget,
        WatchMode,
        TriggerWatch,
        Trigger,
        Verb,
        Exit,
        Location,
        Placement,
        Object,
        Character,
        Outcome,
        Ending,
        Game,
        Point,
        BorderSide,
        BorderAnchor,
        RouteLayout,
        TemplateEntityKind,
        TemplateEntity,
        TemplateContent,
        BlockTemplate,
        EditorLayout,
        WarningAcknowledgement,
        PlaytestSource,
        PlaytestSetup,
        CheckStart,
        CompletionExpectation,
        CheckStep,
        PlaytestCheck,
        PlaytestLibrary,
        Project,
        Severity,
        Diagnostic,
        text::Span,
        ObjectState,
        CharacterState,
        HintProgress,
        GameState,
        HostControl,
        TraceSource,
        TraceChange,
        TraceKind,
        NarrativeOperation,
        ProcedureBinding,
        ProcedureReturn,
        TraceOutcome,
        TraceStep,
        CommandExplanation,
        CommandStatus,
        NounOrigin,
        NounBinding,
        ClarificationChoice,
        ClarificationQuestion,
        UnresolvedInputReason,
        InputResolution,
        CommandResult,
        Draft,
        PanelLayout,
        CanvasPreference,
        EditorPreferences,
        ProjectView,
        ConfigView,
        Configure,
        ContainerActionChoice,
        ContainerActionsRequest,
        NewProject,
        OpenRequest,
        SaveRequest,
        SaveAsRequest,
        ProjectListItem,
        DiskView,
        StartPlaytest,
        CommandRequest,
        ReplyRequest,
        StateRequest,
        PlaytestView,
        CaptureSetup,
        SetupStatusRequest,
        SetupStatus,
        RunCheck,
        CheckStepResult,
        CheckRun
    );
    // Field documentation can leave spaces before newlines in ts-rs output.
    let output = output
        .lines()
        .map(str::trim_end)
        .collect::<Vec<_>>()
        .join("\n")
        + "\n";
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../web/src/contracts.ts");
    if std::env::args().any(|a| a == "--check") {
        ensure!(
            std::fs::read_to_string(path)? == output,
            "TypeScript contracts are stale; regenerate them"
        )
    } else {
        std::fs::write(path, output)?
    }
    Ok(())
}
